using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class ImageProceduralTextureOperations:RefCounted
{
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var value)?value:fallback;
    public Resource copy_recipe(Resource recipe)
    {
        var result=new KiwiImageTextureRecipe();result.Set("kind",recipe.Get("kind"));result.Set("settings",recipe.Get("settings").AsGodotDictionary().Duplicate(true));var noise=recipe.Get("noise_object").AsGodotObject();if(noise!=null)result.Set("noise_object",noise.Call("copy_object"));return result;
    }
    public FastNoiseLite configure_noise(Resource recipe)
    {
        var settings=recipe.Get("settings").AsGodotDictionary();string kind=recipe.Get("kind").AsString();var noiseObject=recipe.Get("noise_object").AsGodotObject();if(noiseObject==null){noiseObject=new ActorObjectData();noiseObject.Set("type_id",new StringName("noise_image"));recipe.Set("noise_object",noiseObject);}int seed=Get(settings,"seed",0).AsInt32(),octaves=Get(settings,"octaves",4).AsInt32();double frequency=Get(settings,"frequency",.035).AsDouble(),gain=Get(settings,"roughness",.5).AsDouble();var type=kind=="perlin"?FastNoiseLite.NoiseTypeEnum.Perlin:kind is "cellular" or "stone"?FastNoiseLite.NoiseTypeEnum.Cellular:FastNoiseLite.NoiseTypeEnum.SimplexSmooth;noiseObject.Set("values",new Settings{[new StringName("seed")]=seed,[new StringName("frequency")]=frequency,[new StringName("octaves")]=octaves,[new StringName("gain")]=gain,[new StringName("noise_type")]=(int)type});return new FastNoiseLite{Seed=seed,Frequency=(float)frequency,NoiseType=type,FractalOctaves=octaves,FractalGain=(float)gain,FractalType=kind is "white" or "smooth" or "perlin" or "simplex"?FastNoiseLite.FractalTypeEnum.None:FastNoiseLite.FractalTypeEnum.Fbm};
    }
    public Image generate(Resource recipe,Vector2I size,Variant cancellation,bool canCancel)
    {
        using var noise=configure_noise(recipe);var config=recipe.Get("settings").AsGodotDictionary();var extent=new Vector2I(Math.Max(1,size.X),Math.Max(1,size.Y));var result=Image.CreateEmpty(extent.X,extent.Y,false,Image.Format.Rgba8);double frequency=Get(config,"frequency",.035).AsDouble()/Math.Max(.01,Get(config,"scale",1).AsDouble());noise.Frequency=(float)frequency;float angle=Mathf.DegToRad((float)Get(config,"rotation",0).AsDouble());double density=Get(config,"density",.5).AsDouble();string kind=recipe.Get("kind").AsString();using var random=new RandomNumberGenerator{Seed=unchecked((ulong)Get(config,"seed",0).AsInt64())};var primary=Get(config,"primary",Colors.Black).AsColor();var secondary=Get(config,"secondary",Colors.White).AsColor();bool seamless=Get(config,"seamless",true).AsBool(),invert=Get(config,"invert",false).AsBool();double contrast=Get(config,"contrast",1).AsDouble(),brightness=Get(config,"brightness",0).AsDouble();var bridge=canCancel?GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_procedural_texture.gd"):null;
        for(int y=0;y<extent.Y;y++){if(canCancel&&bridge!.Call("_cancelled",cancellation).AsBool())return result;for(int x=0;x<extent.X;x++){var point=new Vector2(x,y).Rotated(angle);double value=noise.GetNoise2D(point.X,point.Y)*.5+.5;if(seamless){double u=(double)x/Math.Max(1,extent.X-1),v=(double)y/Math.Max(1,extent.Y-1);var dx=new Vector2(Math.Max(1,extent.X-1),0).Rotated(angle);var dy=new Vector2(0,Math.Max(1,extent.Y-1)).Rotated(angle);double a=noise.GetNoise2D(point.X,point.Y),b=noise.GetNoise2D(point.X-dx.X,point.Y-dx.Y),c=noise.GetNoise2D(point.X-dy.X,point.Y-dy.Y),d=noise.GetNoise2D(point.X-dx.X-dy.X,point.Y-dx.Y-dy.Y);value=((a+(b-a)*u)+((c+(d-c)*u)-(a+(b-a)*u))*v)*.5+.5;}var q=point*(float)frequency;switch(kind){case "white":case "grain":value=random.Randf();break;case "speckles":case "stipple":value=random.Randf()<density*.2?1:0;break;case "paper":value=.75+value*.15+random.Randf()*.1;break;case "fabric":value=.5+.2*Math.Sin(q.X*Math.Tau)*Math.Sin(q.Y*Math.Tau)+value*.1;break;case "stone":value=Math.Pow(Math.Clamp(value,0,1),2);break;case "dirt":value=value*.7+random.Randf()*.3;break;case "clouds":value=Mathf.SmoothStep(.25,.75,value);break;case "scratches":value=Mathf.PosMod(q.X+noise.GetNoise2D(0,point.Y)*.1,1)<density*.03?1:.1;break;case "stripes":value=Mathf.PosMod(q.X,1)<density?1:0;break;case "checkerboard":value=Mathf.PosMod(Mathf.FloorToInt(q.X)+Mathf.FloorToInt(q.Y),2);break;case "grid":value=Math.Min(Mathf.PosMod(q.X,1),Mathf.PosMod(q.Y,1))<density*.2?1:0;break;case "waves":value=.5+.5*Math.Sin(q.X*Math.Tau+Math.Sin(q.Y*Math.Tau));break;case "dots":value=(new Vector2(Mathf.PosMod(q.X,1),Mathf.PosMod(q.Y,1))-Vector2.One*.5f).Length()<density*.5?1:0;break;case "triangles":value=Mathf.PosMod(q.X,1)+Mathf.PosMod(q.Y,1)<density*2?1:0;break;}value=Math.Clamp((value-.5)*contrast+.5+brightness,0,1);if(invert)value=1-value;result.SetPixel(x,y,primary.Lerp(secondary,(float)value));}}
        if(seamless){int band=Math.Max(1,Math.Min(extent.X,extent.Y)/12);for(int y=0;y<extent.Y;y++)for(int index=0;index<band;index++){var a=result.GetPixel(index,y);var b=result.GetPixel(extent.X-1-index,y);var center=a.Lerp(b,.5f);float weight=1-Mathf.SmoothStep(0,band,index);result.SetPixel(index,y,a.Lerp(center,weight));result.SetPixel(extent.X-1-index,y,b.Lerp(center,weight));}for(int x=0;x<extent.X;x++)for(int index=0;index<band;index++){var a=result.GetPixel(x,index);var b=result.GetPixel(x,extent.Y-1-index);var center=a.Lerp(b,.5f);float weight=1-Mathf.SmoothStep(0,band,index);result.SetPixel(x,index,a.Lerp(center,weight));result.SetPixel(x,extent.Y-1-index,b.Lerp(center,weight));}for(int y=0;y<extent.Y;y++)result.SetPixel(extent.X-1,y,result.GetPixel(0,y));for(int x=0;x<extent.X;x++)result.SetPixel(x,extent.Y-1,result.GetPixel(x,0));}return result;
    }
}
